// Code written by Gabriel Mailhot, 21/09/2026.
// The source of all three code bases, parsed once, for the generated maps.
//
// Gabriel, 21/09/2026: "Plus le projet grossit, plus c'est difficile pour moi de voir l'ensemble du systeme. Le vibe
// coding ne produit pas de diagrammes d'architecture... si on implemente une regle dans le code, je ne vois pas si on
// est en train de creer un doublon parce que le concept existe deja ailleurs."
//
// A view of the system has to be GENERATED or it rots: RULES.md was generated by a script somebody had to remember
// to run, and it sat ten days stale while a hundred rules were added. So the maps are regenerated by the test suite
// itself and compared with the committed copy (see ApprovedMap): the trigger is the one pipeline this project already
// has. SYNTAX ONLY, deliberately: it needs no TaleWorlds reference, so the engine-bound mod is mapped exactly like the
// pure layers, and it keeps the XML doc comments, which reflection throws away and which are what make a map readable.

#region

using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

#endregion

namespace CalradiaRemembers.Tests.Maps
{
   /// <summary>Which of the three code bases a file belongs to. The order is the dependency order: Mod may use both others.</summary>
   internal enum Layer
   {
      Mod,
      Logic,
      Sdk
   }

   /// <summary>One parsed source file.</summary>
   internal sealed class SourceFile
   {
      public SourceFile(Layer layer, string relativePath, string text)
      {
         Layer = layer;
         RelativePath = relativePath;
         Text = text;
         Root = CSharpSyntaxTree.ParseText(text, path: relativePath).GetCompilationUnitRoot();
         LineCount = text.Count(c => c == '\n') + 1;
      }

      public Layer Layer { get; }

      /// <summary>Forward slashes, relative to the code base's own folder, so a map reads the same on any machine.</summary>
      public string RelativePath { get; }

      public string Text { get; }
      public CompilationUnitSyntax Root { get; }
      public int LineCount { get; }

      /// <summary>The namespace the file declares (file-scoped or block), or "(global)".</summary>
      public string Namespace
         => Root.DescendantNodes().OfType<BaseNamespaceDeclarationSyntax>().FirstOrDefault()?.Name.ToString() ?? "(global)";
   }

   /// <summary>Finds the two repositories from wherever the tests run, and parses them once per test run.</summary>
   internal static class SourceTree
   {
      private const string ModSolution = "CalradiaRemembers.slnx";
      private const string SdkFolder = "LLM Roleplay Service";

      private static readonly Lazy<string?> ModRepoLazy = new(FindModRepo);
      private static readonly Lazy<IReadOnlyList<SourceFile>> ProductionLazy = new(LoadProduction);
      private static readonly Lazy<IReadOnlyList<SourceFile>> ModTestsLazy = new(() => Load(Layer.Mod, Path.Combine(ModRepo!, "CalradiaRemembers.Tests")));
      private static readonly Lazy<IReadOnlyList<SourceFile>> SdkTestsLazy = new(() => Load(Layer.Sdk, Path.Combine(SdkRepo!, "NpcMemoryServiceTests")));

      /// <summary>The mod repository root, or null when the sources are not reachable from this runner.</summary>
      public static string? ModRepo => ModRepoLazy.Value;

      /// <summary>The SDK repository: the mod's sibling, exactly where its ProjectReference already points.</summary>
      public static string? SdkRepo
      {
         get
         {
            if (ModRepo == null) return null;

            string candidate = Path.Combine(Directory.GetParent(ModRepo)!.FullName, SdkFolder);

            return Directory.Exists(candidate) ? candidate : null;
         }
      }

      /// <summary>
      ///   True when the runner is working on the real tree and all THREE source bases can be read in full. Both
      ///   halves are needed, and each was learned the hard way on 21/09/2026, when map tests failed in NCrunch while
      ///   `dotnet test` was green. First the mod's sources were absent, because NCrunch builds from a workspace copy
      ///   of what the test project REFERENCES and the test project deliberately does not reference the mod (net472,
      ///   engine-bound, unbuildable here), so the maps regenerated without a whole layer. Then, once that was
      ///   guarded, the comparison failed the other way: a workspace carries project SOURCES, but a committed map is
      ///   not part of any project, so a fresh generation was being held against a stale copy of the map.
      ///   <para>
      ///     Hence both a runner check and an anchor check. A map is only meaningful when every layer it describes is
      ///     there AND the copy it is compared with is the one in the repository.
      ///   </para>
      /// </summary>
      public static bool IsReachable => MissingAnchor == null;

      /// <summary>The first layer whose sources are not where they should be, or null when all three are present.</summary>
      public static string? MissingAnchor
      {
         get
         {
            // NCrunch FIRST, before any anchor is looked for. Which tree it hands a test is not ours to predict: it
            // may point at the original solution, or at its own workspace copy, and that copy carries the SOURCES of
            // the projects it builds but not necessarily a current copy of a committed MAP, which is not part of any
            // project. Comparing a fresh generation against a stale copy fails for a reason that has nothing to do
            // with the code, which is exactly what Gabriel saw twice. These tests belong to `dotnet test`.
            if (Environment.GetEnvironmentVariable("NCrunch") == "1")
               return "a runner that works from a workspace copy (NCrunch)";

            if (ModRepo == null) return "the mod repository (no CalradiaRemembers.slnx above this assembly)";
            if (SdkRepo == null) return $"the SDK repository (no '{SdkFolder}' beside the mod)";

            foreach ((string what, string path) in new[] {
                        ("the mod", Path.Combine(ModRepo, "CalradiaRemembers", "GameState", "BannerlordGameStateBridge.cs")),
                        ("Logic", Path.Combine(ModRepo, "CalradiaRemembers.Logic", "ChronicleCalendar.cs")),
                        ("the SDK", Path.Combine(SdkRepo!, "NpcMemoryService.Core", "Prompts", "PromptBuilder.cs"))
                     })
               if (!File.Exists(path)) return $"{what} (expected {path})";

            return null;
         }
      }

      /// <summary>Every production file of the mod, of Logic and of the SDK core. No tests, no tools, no bin/obj.</summary>
      public static IReadOnlyList<SourceFile> Production => ProductionLazy.Value;

      public static IReadOnlyList<SourceFile> ModTests => ModTestsLazy.Value;
      public static IReadOnlyList<SourceFile> SdkTests => SdkTestsLazy.Value;

      #region private

      private static IReadOnlyList<SourceFile> LoadProduction()
      {
         var files = new List<SourceFile>();
         files.AddRange(Load(Layer.Mod, Path.Combine(ModRepo!, "CalradiaRemembers")));
         files.AddRange(Load(Layer.Logic, Path.Combine(ModRepo!, "CalradiaRemembers.Logic")));
         files.AddRange(Load(Layer.Sdk, Path.Combine(SdkRepo!, "NpcMemoryService.Core")));

         return files;
      }

      private static IReadOnlyList<SourceFile> Load(Layer layer, string folder)
         => Directory.EnumerateFiles(folder, "*.cs", SearchOption.AllDirectories)
                     .Select(path => (path, relative: Path.GetRelativePath(folder, path).Replace('\\', '/')))
                     .Where(f => !f.relative.StartsWith("bin/", StringComparison.Ordinal)
                              && !f.relative.StartsWith("obj/", StringComparison.Ordinal)
                              && !f.relative.Contains("/bin/", StringComparison.Ordinal)
                              && !f.relative.Contains("/obj/", StringComparison.Ordinal))
                     .OrderBy(f => f.relative, StringComparer.Ordinal)
                     .Select(f => new SourceFile(layer, f.relative, File.ReadAllText(f.path)))
                     .ToList();

      private static string? FindModRepo()
      {
         // NCrunch runs from a workspace copy, but tells a test where the real solution lives.
         string? ncrunch = Environment.GetEnvironmentVariable("NCrunch.OriginalSolutionPath");
         if (!string.IsNullOrWhiteSpace(ncrunch))
         {
            string? dir = Path.GetDirectoryName(ncrunch);
            if (dir != null && File.Exists(Path.Combine(dir, ModSolution))) return dir;
         }

         for (DirectoryInfo? at = new(AppContext.BaseDirectory); at != null; at = at.Parent)
            if (File.Exists(Path.Combine(at.FullName, ModSolution)))
               return at.FullName;

         return null;
      }

      #endregion
   }
}
